INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "辽史·卷五", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/4a7f7d906bca2ed23df36ebba9c517df6c6e2446/content/books/zizhi-tongjian/vol-286/year-0947/part-03/sources/library/liaoshi-005-yelu-ruan/source.txt", "note": "《辽史》卷五，段落 liaoshi-7cd182a20e67-p000588；EPUB电子本，纸本及异文待核", "id": "a940f205-c945-5546-9dcc-493aaad78557"}, {"title": "资治通鉴·后汉纪一", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/4a7f7d906bca2ed23df36ebba9c517df6c6e2446/content/books/zizhi-tongjian/vol-286/year-0947/part-03/sources/library/tongjian-286-947-jin-army/source.txt", "note": "《资治通鉴》后汉纪一，段落 zizhi-tongjian-a63549944a71-p003395；电子底本待考，分段待核", "id": "21c9ad89-1dce-55af-a80c-e80b4d8dee80"}, {"title": "旧五代史·卷八十五", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d4c559b31fae71400d51ba9fe66160d5967ce6ca/content/books/zizhi-tongjian/vol-286/year-0947/part-02/sources/library/jiuwudaishi-085-947-january/source.txt", "note": "《旧五代史》卷八十五，段落 jiu-wudaishi-205deb4a7860-p002052；EPUB电子本，纸本及异文待核", "id": "548fcb32-173b-54f8-a340-102667e40687"}, {"title": "辽史·卷四", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a5d9d0eaf47ddcb551bf8ebe17a51e9f9ee98221/content/books/zizhi-tongjian/vol-286/year-0947/part-01/sources/library/liaoshi-004-947-january/source.txt", "note": "《辽史》卷四，段落 liaoshi-7cd182a20e67-p000579；EPUB电子本，纸本及异文待核", "id": "e7449583-ec7a-55df-bb14-13daf37aa21c"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "杜重威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔州人，后晋将领，妻子是石敬瑭的妹妹乐平长公主。937年以护圣都指挥使身份率军驻卫州。", "biography": null, "status": "draft", "id": "e5e23c10-447f-5238-bc56-f376300f9bac"}, {"name": "赵延寿", "aliases": ["趙延壽", "延寿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：赵延寿，公主丈夫。", "biography": null, "status": "draft", "id": "bf502cd0-4cbb-52e5-b93a-e30caa907a58"}, {"name": "李彦绅", "aliases": ["李彥紳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李彦绅，皇城使、受遣者。", "biography": null, "status": "draft", "id": "fe7a8a9f-1ada-5fe5-a666-d189608f6b35"}, {"name": "秦继旻", "aliases": ["秦繼旻"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：秦继旻，受遣宦者。", "biography": null, "status": "draft", "id": "1c8a6085-d929-5240-ad5e-11ec65c76f8c"}, {"name": "耶律阮", "aliases": ["耶律兀欲", "兀欲", "永康王"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "小字兀欲，东丹王耶律倍之子。《资治通鉴》947年条下称永康王，记耶律德光将李彦绅、秦继旻的家属和财产交给他。《辽史》卷五明确名阮、小字兀欲，按同一主体建档；王号具体授封时间仍须另据后文校核，生卒年暂未录。", "biography": null, "status": "draft", "id": "42a17de5-aa28-50e6-bab8-b134f0113f3f"}, {"name": "耶律倍", "aliases": ["突欲", "托云", "李赞华", "李贊華", "李讚華", "李赞化", "李贊化"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律倍，镇东丹、受号人皇王的长子。", "biography": null, "status": "draft", "id": "5627be02-e5b4-58fd-9c04-9871554a8d80"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "永宁公主（石敬瑭妻）", "aliases": ["永宁公主", "永寧公主"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：永宁公主（石敬瑭妻），与从荣异母的公主。", "biography": null, "status": "draft", "id": "fddc7a96-9cc5-5313-ac24-2c3189930825"}, {"name": "安氏（石重贵母）", "aliases": ["安氏"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安氏（石重贵母），石重贵之母亲。", "biography": null, "status": "draft", "id": "007fcf3c-6da4-54ec-9554-a112cebe061f"}, {"name": "冯氏（石重贵后）", "aliases": ["吴国夫人冯氏", "馮氏（石重贵后）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冯濛的女儿、冯玉的妹妹。先嫁石重胤，夫死后守寡；石敬瑭去世后被石重贵纳入宫中，943年十月戊申由吴国夫人立为皇后，随后参与政务。具体个人名字与生卒年未载。", "biography": null, "status": "draft", "id": "a9036cf2-4b6b-5883-a952-511979eb35f7"}, {"name": "石重睿", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "石敬瑭的幼子。942年石敬瑭病中让他拜见冯道，并由宦者抱入冯道怀中；史书解释为托付之意。石敬瑭去世后，大臣以多事为由拥立石重贵，石重睿未能继位。生卒年未载。", "biography": null, "status": "draft", "id": "361f2434-8f22-5818-b912-366e1a3e8af8"}, {"name": "石延煦", "aliases": ["延煦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "石敬瑭的孙子，石重贵养子，石延宝的兄长。946年任镇宁节度使，与赵在礼的女儿成婚；《资治通鉴》记三月庚申，《旧五代史》记四月，婚事纪月不同，分别保留。亲生父母姓名及生卒年未载。", "biography": null, "status": "draft", "id": "ed348273-f4e9-5b33-9080-aa449de66dcc"}, {"name": "石延宝", "aliases": ["石延寶", "延宝", "延寶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "石敬瑭的孙子，石重贵养子，石延煦的弟弟。946年记石延煦婚事时，史书补叙二人为石重贵养子。亲生父母姓名与收养年月、生卒年未载。", "biography": null, "status": "draft", "id": "79b31372-7a96-5605-a27f-799f2f8a9daf"}, {"name": "赵莹", "aliases": ["趙瑩"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：赵莹，劝赴任者。", "biography": null, "status": "draft", "id": "1f5a50e7-b046-593f-8be4-621934211b27"}, {"name": "冯玉", "aliases": ["馮玉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冯皇后的兄长，后晋官员。《资治通鉴》记其由礼部郎中、盐铁判官被迅速擢为端明殿学士、户部侍郎；《旧五代史》另记知制诰、中书舍人、颍州团练使等任职。各书路径分别保留，生卒年本批未核。", "biography": null, "status": "draft", "id": "b4626ebf-1219-5b9b-baca-73e491e175f8"}, {"name": "李彦韬（后晋宣徽使）", "aliases": ["李彥韜（後晉宣徽使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，早年曾侍奉阎宝，后来入石敬瑭帐下并留在太原侍奉石重贵。945年任宣徽北院使、暂代侍卫马步都虞候，与冯玉争桑维翰的权力。与早期曾名李彦韬的温韬分档，温韬在后唐明宗时已被赐死。生卒年本段未载。", "biography": null, "status": "draft", "id": "e4ac4a2d-843f-5686-98da-4b16e23f906d"}, {"name": "李谷", "aliases": ["李穀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：李谷，汝阴进士、送别友人。", "biography": null, "status": "draft", "id": "33cb8b51-1e37-5d5f-ab22-b339b991020d"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
